<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Books catalogue';$basePath='../';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'';if($act==='save'){$id=(int)($_POST['id']??0);$title=trim($_POST['title']);$author=trim($_POST['author']);$total=max(1,(int)$_POST['total_copies']);$avail=max(0,(int)$_POST['available_copies']);$avail=min($avail,$total);if($id){$s=$pdo->prepare('UPDATE books SET title=?,author=?,isbn=?,category=?,publisher=?,shelf=?,total_copies=?,available_copies=? WHERE id=?');$s->execute([$title,$author,$_POST['isbn'],$_POST['category'],$_POST['publisher'],$_POST['shelf'],$total,$avail,$id]);audit($pdo,'Updated book',$title);}else{$s=$pdo->prepare('INSERT INTO books(title,author,isbn,category,publisher,shelf,total_copies,available_copies) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$title,$author,$_POST['isbn'],$_POST['category'],$_POST['publisher'],$_POST['shelf'],$total,$total]);audit($pdo,'Added book',$title);}flash('success','Book saved.');redirect('books.php');}if($act==='delete'){$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT COUNT(*) FROM loans WHERE book_id=?');$s->execute([$id]);if($s->fetchColumn()>0)flash('error','This book has loan history and cannot be deleted.');else{$pdo->prepare('DELETE FROM books WHERE id=?')->execute([$id]);flash('success','Book deleted.');}redirect('books.php');}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM books WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT * FROM books WHERE title LIKE ? OR author LIKE ? OR isbn LIKE ? ORDER BY id DESC');$like="%$q%";$s->execute([$like,$like,$like]);$books=$s->fetchAll();require __DIR__.'/../includes/layout_top.php';?>
<div class="two-col"><div class="panel"><div class="panel-head"><div><h3><?=$edit?'Edit book':'Add a book'?></h3><p>Catalogue information and available copies.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label class="wide">Book title<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Author<input name="author" required value="<?=e($edit['author']??'')?>"></label><label>ISBN<input name="isbn" value="<?=e($edit['isbn']??'')?>"></label><label>Category<input name="category" value="<?=e($edit['category']??'')?>"></label><label>Publisher<input name="publisher" value="<?=e($edit['publisher']??'')?>"></label><label>Shelf / rack<input name="shelf" value="<?=e($edit['shelf']??'')?>"></label><label>Total copies<input type="number" min="1" name="total_copies" value="<?=e($edit['total_copies']??1)?>"></label><?php if($edit):?><label>Available copies<input type="number" min="0" name="available_copies" value="<?=e($edit['available_copies'])?>"></label><?php endif;?><div class="wide form-actions"><button class="btn primary">Save book</button><?php if($edit):?><a class="btn" href="books.php">Cancel</a><?php endif;?></div></form></div><div class="panel"><div class="panel-head"><div><h3>Catalogue</h3><p><?=count($books)?> matching titles</p></div></div><form class="search-row"><input name="q" placeholder="Search title, author or ISBN" value="<?=e($q)?>"><button class="btn">Search</button></form><div class="table-wrap"><table><thead><tr><th>Book</th><th>Copies</th><th>Action</th></tr></thead><tbody><?php foreach($books as $b):?><tr><td><b><?=e($b['title'])?></b><small><?=e($b['author'])?> · <?=e($b['isbn'])?></small></td><td><?=$b['available_copies']?> / <?=$b['total_copies']?></td><td class="actions"><a href="?edit=<?=$b['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this book?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="link danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$books):?><tr><td colspan="3" class="empty">No books found.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
